struct HITINFO{
    vec3 point;
    vec3 normal;
    bool didhit;
};

float random(float x) {
    return fract(sin(x*1000.0+1.0));
}
float easing(float x) {
    return x*x*x*(6.0*x*x - 15.0*x + 10.0);
}
float perlin(float x) {
    float fX = floor(x);
    float t = easing(fract(x));
    return random(fX) * (1.0-t) + random(fX+1.0)*t;
}
vec3 randomDir(float x) {
    float X = 2.0*perlin(x)-1.0;
    float Y = 2.0*perlin(x+5.33)-1.0;
    float Z = 2.0*perlin(x+10.66)-1.0;
    vec3 p = vec3(X,Y,Z);

    return normalize(p);
}

float distanceToDonut(vec3 C, vec3 N, float R, float r, vec3 P) {
    vec3 CP = P-C; 
    return length(normalize(CP-N*dot(N,CP))*R - CP) - r;
}
vec3 DonutNormal(vec3 C, vec3 N, float R, vec3 P) {
    vec3 CP = P-C; 
    return normalize(CP - normalize(CP-N*dot(N,CP))*R);
}

HITINFO HITDONUT(vec3 C, vec3 N, float R, float r, vec3 O, vec3 D) {
    float t = 0.0;
    vec3 P = O;
    for(int i = 0; i < 200; i++) {
        float d = distanceToDonut(C, N, R, r, P);
        t += d;
        P = P+D*d;
        if(d < 0.0001) {
            HITINFO hitinfo;
            hitinfo.point = P;
            hitinfo.normal = DonutNormal(C, N, R, P);
            hitinfo.didhit = true;
            return hitinfo;
        }
        else if(t > 100.0) break;
    }
    HITINFO hitinfo;
    hitinfo.didhit = false;
    return hitinfo;
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv = 2.0*uv-1.0;
    uv.x *=iResolution.x/iResolution.y;
    vec3 D = normalize(vec3(uv,1.0));
    vec3 O = vec3(0.0,0.0,-3.0);
    vec3 C = vec3(0.0);
    vec3 N = randomDir(iTime);

    vec3 normal = HITDONUT(C, N, 1.0, 0.4, O, D).normal;
    vec3 R = reflect(D, normal);

    vec4 color = texture(iChannel0, R);



    // Output to screen
    fragColor = vec4(color);
}
